insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('04a6de5e-f4f9-494a-ab4b-f09210177d08', '0a237d4f-9ff1-496e-aae4-83b153770acd', 12, 'controls', 'KPIs, cost, and decisions (2)', 'case: CSCO-AID-ENT-001
title: Cisco AI Defense for building and using enterprise AI
industry: Cross-industry (cross_industry)
segment: Enterprise
solutions: Cisco AI Defense, Cisco Security Cloud, Cisco Talos
partners: Splunk
aliases: AI Defense, shadow AI, model validation, runtime protection, Security Cloud
fidelity: primary_source
Cost planning band
Amounts and durations are planning bands for a first subscription pilot. They are not a list price and not a customer result.
- AI Defense pilot subscription (opex): 150000–800000 USD. Planning band. Confirm the SKU.
- Test design and readout (opex): 40000–200000 USD. Internal security time can replace part of this.
- Splunk enrichment (opex): 0–150000 USD. Zero if Splunk is already owned and in scope. Not a new promise otherwise.

Decisions
- D1 What 29 percent means: A Cisco citation of the 2024 AI Readiness Index. Not this pilot''s baseline.. The announcement cites the survey. It does not measure this customer.
- D2 Where segmentation lives: A data-center or financial segmentation design points at CSCO-HYP-FIN-001. This record stays the source card.. The announcement does not publish a bank''s segmentation result.', 591, '[-0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.092748,0.000000,0.000000,0.139122,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.092748,-0.278243,0.000000,0.000000,0.046374,0.000000,0.000000,0.000000,0.000000,-0.139122,0.000000,-0.231869,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046374,0.000000,0.000000,0.000000,-0.046374,0.000000,0.000000,0.000000,0.000000,0.046374,-0.092748,0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046374,0.000000,0.000000,0.046374,0.000000,0.092748,0.000000,0.000000,0.000000,0.000000,0.000000,0.046374,-0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.046374,0.000000,0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.139122,0.000000,-0.231869,0.185496,0.000000,0.000000,-0.046374,0.000000,0.000000,0.000000,0.000000,0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.092748,0.000000,0.000000,0.000000,-0.092748,0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.092748,0.324617,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.046374,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046374,0.046374,0.000000,0.000000,0.000000,0.000000,-0.092748,0.139122,0.000000,0.000000,-0.046374,0.000000,0