insert into solution_cases (
  id, case_code, slug, title, title_en, record_type, fidelity, fidelity_note, status, confidentiality,
  executive_summary, problem_statement, opportunity, strategic_alignment, business_value,
  industry, industry_label, customer_segment, customer_segment_label, region, regulatory_context,
  company_size_band, deployment_model, deployment_model_label, architecture_pattern, complexity,
  planning_band_note, deal_size_low_usd, deal_size_high_usd, deal_size_band,
  lead_time_weeks_low, lead_time_weeks_high, duration_weeks_low, duration_weeks_high,
  cisco_solutions, partner_technologies, ai_capabilities, security_capabilities, aliases,
  scope_in, scope_out, success_criteria, outcome_type, outcomes, video_url, video_title, published_on
) values (
  'c6a9af38-c92a-4038-af87-c598f38ee3cc', 'CSCO-HYP-FIN-001', 'hypershield-finance-visibility', 'Financial-services visibility and access control for AI apps with Hypershield and AI Defense', 'Financial-services visibility and access control for AI apps with Hypershield and AI Defense',
  'reference_scenario', 'public_composite', 'A planning scenario composed from Cisco''s public AI Defense and Hypershield material, placed under financial-services constraints. It is not a bank''s results. No customer name, quote, or measured MTTR is stored here.', 'published', 'public',
  'A financial institution wants to see which AI applications touch customer and transaction data, and to control that access, before any enforce mode. The public ingredients are AI Defense for discovery and runtime protection, and Hypershield for distributed enforcement with a dual data plane so a policy can be observed before it is enforced. The PM plan is a shadow-mode pilot, a rollback, and a separate decision to enforce. Minutes-to-mitigate is a published product design goal, not a measured customer result.', 'AI applications in a bank cross model providers, lines of business, and the data center. Security can see the network and still not see which application is an AI application, or which one is unapproved. Turning on enforcement before the inventory exists blocks legitimate work and still misses the unknown app.', 'Cisco''s public Hypershield design describes enforcement close to the workload and upgrades that qualify themselves on a dual data plane. AI Defense adds discovery of shadow and approved AI, model validation, and runtime controls. Together they give a sequence: discover, observe, then decide whether to enforce.', 'The control objective is visibility and a reversible policy, aligned to electronic-financial supervision, privacy, and credit-information duties. Speed of mitigation is not the acceptance test.', 'The sponsor can point at an inventory, an observation report, and a written enforce-or-hold decision. The program does not claim a percentage reduction in MTTR.',
  'financial_services', 'Financial services', 'enterprise', 'Enterprise financial institution', 'APAC', array['Regulation on Supervision of Electronic Financial Transactions', 'Personal Information Protection Act', 'Credit Information Act', 'NIST AI RMF', 'OWASP LLM Top 10'],
  'Enterprise bank or insurer', 'hybrid', 'Hybrid, shadow mode before enforcement', 'AI Defense discovers applications and watches runtime use. Hypershield places enforcement in the data center and cloud fabric. New policy runs in shadow on the second data plane. Enforcement waits for the CISO''s decision. Talos informs detection. Splunk is the investigation store only if it is already deployed.', 'high',
  'The 750,000 to 2,500,000 US dollar range and the week ranges are planning bands for a first financial pilot. They are not a quote and not a bank''s spend.', 750000, 2500000, 'L',
  6, 12, 16, 28,
  array['Cisco AI Defense', 'Cisco Hypershield', 'Cisco Security Cloud', 'Cisco Talos', 'Splunk'], array[]::text[], array['Shadow AI discovery', 'Runtime protection', 'Policy observation before enforcement'], array['Distributed enforcement', 'Dual data plane', 'Rollback', 'Access control for AI applications'], array['Hypershield', 'financial services', 'visibility', 'shadow mode', 'AI Defense', 'segmentation'],
  array['One business line and the AI applications that touch its data', 'An inventory of approved and unapproved AI applications', 'Shadow-mode observation with a rollback', 'A written decision before enforce mode'], array['Naming a bank that has not been named in the input', 'An MTTR percentage', 'Enforce mode during the observation window', 'A full data-center fabric replacement'], array['The inventory separates approved and unapproved AI applications', 'The observation report lists what shadow mode would have blocked', 'Enforce mode is a signed decision, default hold'], 'expected_planning', array['Planning outcome: an inventory and a shadow-mode report for one business line. This is not a published customer result.', 'Published design goal: Hypershield describes mitigation in minutes and self-qualifying upgrades on a dual data plane. That is Cisco''s product design, not a measured bank outcome.', 'Published fact: AI Defense, announced 15 January 2025, covers discovery, validation, runtime protection, and access control.'],
  null, null, '2025-01-15'
);
