insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('479e28de-b5b9-461b-a79f-baeb882dfa6c', 'c6a9af38-c92a-4038-af87-c598f38ee3cc', 0, 'business_case', 'Business case (1)', 'case: CSCO-HYP-FIN-001
title: Financial-services visibility and access control for AI apps with Hypershield and AI Defense
industry: Financial services (financial_services)
segment: Enterprise financial institution
solutions: Cisco AI Defense, Cisco Hypershield, Cisco Security Cloud, Cisco Talos, Splunk
partners: 
aliases: Hypershield, financial services, visibility, shadow mode, AI Defense, segmentation
fidelity: public_composite
A financial institution wants to see which AI applications touch customer and transaction data, and to control that access, before any enforce mode. The public ingredients are AI Defense for discovery and runtime protection, and Hypershield for distributed enforcement with a dual data plane so a policy can be observed before it is enforced. The PM plan is a shadow-mode pilot, a rollback, and a separate decision to enforce. Minutes-to-mitigate is a published product design goal, not a measured customer result.

Problem: AI applications in a bank cross model providers, lines of business, and the data center. Security can see the network and still not see which application is an AI application, or which one is unapproved. Turning on enforcement before the inventory exists blocks legitimate work and still misses the unknown app.', 636, '[-0.043315,0.000000,-0.086630,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.043315,0.000000,0.000000,0.000000,0.043315,-0.086630,0.000000,0.000000,0.000000,0.000000,0.043315,0.000000,0.000000,0.000000,0.086630,-0.259889,0.000000,0.000000,0.043315,0.000000,0.000000,0.000000,0.043315,-0.129944,0.129944,-0.433148,0.043315,0.000000,0.000000,0.000000,0.000000,-0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.216574,0.043315,0.000000,0.043315,0.000000,0.000000,-0.043315,0.043315,0.000000,0.086630,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.000000,0.000000,0.000000,-0.043315,0.000000,0.000000,0.000000,-0.043315,0.000000,-0.043315,0.000000,-0.043315,0.000000,0.000000,0.000000,-0.043315,0.000000,-0.129944,0.000000,0.000000,0.086630,-0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.043315,-0.259889,0.000000,0.000000,0.000000,-0.043315,0.043315,0.000000,0.043315,0.000000,0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.129944,0.000000,0.000000,0.043315,0.000000,0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.346518,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.043315,0.000000,0.000000,0.000000,0.000000,0.043315,-0.043315,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.0000