insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('1a36a7c7-020e-49fc-a210-53100eb2e4d2', 'c6a9af38-c92a-4038-af87-c598f38ee3cc', 5, 'scope', 'Scope, assumptions, and constraints (1)', 'case: CSCO-HYP-FIN-001
title: Financial-services visibility and access control for AI apps with Hypershield and AI Defense
industry: Financial services (financial_services)
segment: Enterprise financial institution
