) values (
  '90161c79-3646-4eb6-a438-a1a0241625b5', 'CSCO-AIF-NVD-001', 'secure-ai-factory-nvidia', 'Enterprise AI factory pilot on the Cisco and NVIDIA reference architecture', 'Enterprise AI factory pilot on the Cisco and NVIDIA reference architecture',
  'public_announcement', 'primary_source', 'The architecture facts are Cisco newsroom statements from February, March, and June 2025. The cost and schedule are planning bands for a small enterprise pilot pod. They are not a quote and not a hyperscale build.', 'published', 'public',
  'Cisco and NVIDIA published a Secure AI Factory pattern that ties UCS AI, Hyperfabric AI, Silicon One, Spectrum-X, certified storage, and NVIDIA AI Enterprise. Later public notes place AI Defense and Hypershield in the validated design. A PM uses the publications to freeze one pod: GPU count, rack, storage partner, and NOS. The first success is one fine-tune or one inference job, plus a security observation report. A full factory is out of scope.', 'Training and inference split across a front-end network, a back-end network, GPU-to-GPU traffic, storage, and security. Buying those separately produces two operating models. Some organizations cannot put the data in a public cloud. A prototype then has no path to production.', 'The February 2025 partnership note says Silicon One is the only partner silicon planned for Spectrum-X Ethernet. The March 2025 Secure AI Factory announcement bundles the compute, fabric, storage, and software. The June 2025 note includes AI Defense and Hypershield in the NVIDIA Enterprise AI Factory validated design.', 'Size the pod to one validation job. Power, export control, and a security observation mode come before the purchase order.', 'The sponsor has a signed scale card and one finished job on that pod. Roadmap features that cannot be ordered today are not success criteria.',
  'technology', 'Technology and infrastructure', 'enterprise_neocloud', 'Enterprise and neocloud', 'Global', array['Data residency', 'NIST AI RMF', 'GPU export controls'],
  'One GPU pod', 'on_prem', 'On premises', 'UCS AI servers, a Silicon One and Hyperfabric AI Ethernet fabric with optional Spectrum-X, certified storage, NVIDIA AI Enterprise, and security observation through AI Defense and Hypershield. Front-end and back-end networks share one operating model.', 'very_high',
  'Price moves with GPU count. The band below is a small enterprise pilot pod, not a quote.', 2000000, 15000000, 'XL',
  12, 24, 24, 52,
  array['Cisco UCS', 'Nexus Hyperfabric AI', 'Cisco Silicon One', 'Cisco AI Defense', 'Cisco Hypershield'], array['NVIDIA AI Enterprise', 'NVIDIA Spectrum-X', 'Certified storage partner'], array['One fine-tune or inference validation job', 'Cluster scheduling on the pilot pod'], array['Observation mode before enforce', 'Rollback', 'Residency check on training data'], array['Secure AI Factory', 'NVIDIA', 'GPU pod', 'Spectrum-X', 'Hyperfabric'],
  array['A scale card with GPU count, racks, one storage partner, and NOS', 'One operating model for front-end and back-end networks', 'Security controls in observation mode', 'One validation job, either fine-tune or inference'], array['A hundreds-of-thousands-GPU neocloud', 'A roadmap feature that cannot be ordered today, used as a success criterion', 'Full pretraining of a foundation model on customer data'], array['A signed scale card names GPUs, storage, and NOS', 'One validation job finishes on the pod', 'A security observation report and a rollback exist'], 'published', array['Published fact, February 2025: Silicon One is described as the only partner silicon planned for Spectrum-X Ethernet.', 'Published fact, March 2025: Secure AI Factory bundles UCS AI, Hyperfabric AI, Silicon One, Spectrum-X, certified storage, and NVIDIA AI Enterprise.', 'Published fact, June 2025: AI Defense and Hypershield are included in the NVIDIA Enterprise AI Factory validated design.'],
  null, null, '2025-03-18'
);
