insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('3becf31c-44af-4008-a01c-40b54ee0b391', '6a1f505b-a8be-4fea-a086-6a30326ea6ff', 0, 'business_case', 'Business case (1)', 'case: CSCO-WX-AIM-001
title: Governance plan for Webex specialized models and security-product LLM use
industry: Collaboration (workplace)
segment: Enterprise
solutions: Webex, Webex AI, Cisco AI security proxy
partners: 
aliases: Webex, noise removal, virtual background, gesture, LLM, bias
fidelity: public_composite
Turning on Webex AI features needs a per-feature data-flow table before a single policy. Cisco''s public notes say noise removal runs on the device, virtual backgrounds were trained across lighting and groups and then tested for bias, and gesture recognition uses a model from consented internal data. Meeting summaries and a security-product LLM are a different path: prompts, a proxy, and a person. The default is that customer content is not used to train the model.

Problem: Switching collaboration AI on as one feature mixes privacy, bias, and meeting content leaving for an external model. A security team that says it will build its own LLM then has a project with no data rights and no evaluation. Each feature moves data differently, and the policy is still one page.', 548, '[-0.050572,0.101144,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,-0.050572,0.050572,-0.050572,0.050572,0.000000,0.000000,0.000000,0.000000,-0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.050572,-0.202289,0.000000,0.000000,0.050572,-0.050572,0.000000,-0.101144,0.050572,-0.101144,0.101144,-0.455150,0.000000,-0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,-0.151717,0.000000,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,-0.151717,0.000000,-0.151717,0.000000,0.000000,0.050572,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.151717,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.050572,0.000000,-0.050572,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.050572,0.101144,0.000000,0.050572,0.000000,0.000000,-0.252861,0.000000,0.000000,0.101144,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.101144,-0.202289,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,-0.050572,0.050572,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,-0.151717,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.050572,0.000000,0.202289,0.000000,0.000000,0.000000,0.000000,0.000000,0.050572,0.000000,0.000000,0.000000,0.000000,-0.050572,0.000000,-0.151717,0.050572,0.000000,0.000000,-0.101144,0.050572,0.000000,0.000000,0.000000,0.000000,-0.050572,0.000000,0.