insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('8735e245-5a07-409b-a843-d3b3ef74d5dd', '6a1f505b-a8be-4fea-a086-6a30326ea6ff', 1, 'business_case', 'Business case (2)', 'case: CSCO-WX-AIM-001
title: Governance plan for Webex specialized models and security-product LLM use
industry: Collaboration (workplace)
segment: Enterprise
solutions: Webex, Webex AI, Cisco AI security proxy
partners: 
aliases: Webex, noise removal, virtual background, gesture, LLM, bias
fidelity: public_composite
Opportunity: Cisco''s public material separates, by feature, an AI impact assessment, training-data review, on-device processing, and a security LLM proxy. A PM can turn that separation into requirements and tests.

Strategic alignment: Features with a published on-device path can be piloted first. Anything that sends content to a model waits for the data-flow row and the impact assessment.

Business value: The organization keeps a list of features that may be on and features that need more review. The security LLM is not wired to an automatic action before an evaluation set exists.', 454, '[-0.125988,0.062994,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,-0.062994,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.062994,-0.251976,0.000000,0.000000,0.062994,-0.062994,0.000000,0.000000,0.000000,-0.125988,0.000000,-0.314970,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.125988,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.125988,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,-0.062994,0.062994,0.000000,0.000000,0.000000,0.000000,-0.188982,0.062994,0.000000,0.062994,0.000000,0.000000,-0.251976,0.062994,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.125988,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,-0.251976,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.125988,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.125988,0.000000,0.000000,-0.062994,0.000000,0.000000,0.062994,0.000000,0.188982,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.251976,0.125988,0.000000,0.000000,0.000000,0.062994,0.000000,0.000000,0.000000,0.000000,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,-0.062994,0.062994,-0.062994,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,