  company_size_band, deployment_model, deployment_model_label, architecture_pattern, complexity,
  planning_band_note, deal_size_low_usd, deal_size_high_usd, deal_size_band,
  lead_time_weeks_low, lead_time_weeks_high, duration_weeks_low, duration_weeks_high,
  cisco_solutions, partner_technologies, ai_capabilities, security_capabilities, aliases,
  scope_in, scope_out, success_criteria, outcome_type, outcomes, video_url, video_title, published_on
) values (
  'daa516ad-c6d2-44c7-a928-93832b0bc4d4', 'CSCO-SIO-DC-001', 'silicon-one-ai-fabric', 'Internal IT plan for an AI-ready Silicon One Ethernet fabric', 'Internal IT plan for an AI-ready Silicon One Ethernet fabric',
  'reference_scenario', 'public_composite', 'Public descriptions of Silicon One, Hyperfabric AI, 400G BiDi, Unified Nexus Dashboard, Intelligent Packet Flow, and Hypershield self-qualifying upgrades, recomposed as an internal IT program. No public record in this bank shows a customer finishing a whole data center in a few weeks. The few-week window applies only to the pilot pod after the hardware arrives.', 'published', 'public',
  'Internal network and IT teams replace an Ethernet data center path so AI jobs can land on it. The materials are Silicon One, an optional Spectrum-X link for front-end and back-end networks, 400G BiDi so existing multimode fiber can stay, a unified dashboard, and congestion-aware traffic adjustment. Non-disruptive means a Hypershield dual-data-plane upgrade and an optic move that does not pull out the current fiber. The program is planned at 16 to 32 weeks. The first pilot pod, after hardware arrives, is planned at 6 to 10 weeks.', 'The data center was built for general east-west traffic. AI jobs add a back-end fabric, new optics, and a security policy that cannot take a long outage. A plan that promises the whole hall in a few weeks mixes a pilot window with a program.', 'Cisco''s public notes describe 400G BiDi on existing dual multimode fiber, a Silicon One Ethernet fabric, and Hypershield upgrades that switch on a second data plane. Unified Nexus Dashboard and Intelligent Packet Flow are the operations pieces.', 'Survey the fiber first. Order only what the survey supports. Put the pilot into the existing change window. Leave model training itself to the AI factory case.', 'Operations inherits a pilot pod it can run with the current runbook, and a written rehearsal for policy changes. The program does not claim a whole-site cutover.',
  'technology', 'Technology and infrastructure', 'internal_it', 'Internal IT', 'APAC', array['Change-management policy', 'Data-center physical access', 'Maintenance-window rules'],
  'Internal IT', 'on_prem', 'On premises', 'Silicon One Ethernet fabric, optional Spectrum-X, NX-OS or SONiC, 400G BiDi, Unified Nexus Dashboard, Intelligent Packet Flow. Security policy changes use the Hypershield dual data plane.', 'high',
  'Amounts follow the pod and the optic scope. They are not the cost of replacing a data center in a few weeks.', 1500000, 8000000, 'L',
  8, 16, 16, 32,
  array['Cisco Silicon One', 'Nexus Hyperfabric AI', 'Nexus Dashboard', 'Cisco Hypershield'], array['NVIDIA Spectrum-X'], array['Fabric ready for an AI pod', 'Congestion-aware traffic adjustment'], array['Dual data plane for policy changes', 'Existing change window'], array['Silicon One', 'data center', '400G', 'Hyperfabric', 'fabric', 'BiDi'],
  array['Fabric design for one hall or one pod', 'A split between spans that need 400G and spans that reuse fiber', 'The operations-dashboard scope', 'A dual-plane rehearsal for a security policy change', 'A 6 to 10 week pilot start after hardware arrives'], array['Campus and overseas sites', 'A success criterion that the whole data center finishes in a few weeks', 'Training the model itself, which is the AI factory case'], array['The survey and the migration method are written per span', 'The pilot pod runs inside the existing change window', 'The policy rehearsal is the non-disruptive procedure on file'], 'expected_planning', array['Planning outcome: the first pod joins the internal change procedure. Not a published customer result.', 'Published design: 400G BiDi keeps the existing dual multimode fiber.', 'Published design: Hypershield upgrades switch on a dual data plane.'],
  null, null, '2025-06-01'
);
