insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('a1e5a17d-8cbd-487e-abf3-05055e00f4c8', 'daa516ad-c6d2-44c7-a928-93832b0bc4d4', 0, 'business_case', 'Business case (1)', 'case: CSCO-SIO-DC-001
title: Internal IT plan for an AI-ready Silicon One Ethernet fabric
industry: Technology and infrastructure (technology)
segment: Internal IT
solutions: Cisco Silicon One, Nexus Hyperfabric AI, Nexus Dashboard, Cisco Hypershield
partners: NVIDIA Spectrum-X
aliases: Silicon One, data center, 400G, Hyperfabric, fabric, BiDi
fidelity: public_composite
Internal network and IT teams replace an Ethernet data center path so AI jobs can land on it. The materials are Silicon One, an optional Spectrum-X link for front-end and back-end networks, 400G BiDi so existing multimode fiber can stay, a unified dashboard, and congestion-aware traffic adjustment. Non-disruptive means a Hypershield dual-data-plane upgrade and an optic move that does not pull out the current fiber. The program is planned at 16 to 32 weeks. The first pilot pod, after hardware arrives, is planned at 6 to 10 weeks.

Problem: The data center was built for general east-west traffic. AI jobs add a back-end fabric, new optics, and a security policy that cannot take a long outage. A plan that promises the whole hall in a few weeks mixes a pilot window with a program.', 580, '[-0.140334,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.093556,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.093556,0.000000,-0.046778,0.000000,0.000000,0.093556,0.000000,0.000000,0.000000,0.046778,-0.327446,0.000000,0.000000,0.046778,0.000000,0.000000,-0.093556,0.046778,-0.093556,0.140334,-0.467780,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.093556,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,-0.046778,0.000000,0.000000,0.046778,0.000000,0.046778,0.000000,0.000000,-0.046778,0.000000,0.000000,0.093556,0.000000,0.046778,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,-0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.187112,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,-0.093556,0.187112,0.000000,0.046778,0.000000,0.000000,-0.046778,0.000000,0.000000,0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.046778,-0.140334,0.000000,-0.046778,0.000000,-0.140334,0.000000,0.000000,0.093556,0.000000,0.046778,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,-0.140334,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.093556,0.000000,-0.046778,0.000000,0.000000,0.000000,-0.093556,0.140334,-0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046778,0.000000,-0.140334,0.093556,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.046778,0.046778,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000