) values (
  'c0445a81-159a-4efb-a7a1-4c850784412b', 'CSCO-XDR-SOC-001', 'xdr-ai-security-operations', 'AI-assisted security operations with Cisco XDR', 'AI-assisted security operations with Cisco XDR',
  'video_demo', 'primary_source', 'Built from the CiscoKorea demonstration video, the XDR AI white paper, and the public notes on Instant Attack Verification and the agentic SOC. The video is a demo, not a work instruction, and it is not a measured time-saved percentage. High-impact actions stay with a person.', 'published', 'public',
  'Cisco XDR''s public AI story is a draft for the analyst: summarize the incident, point at the evidence, and let a person decide. Instant Attack Verification, Talos, Secure Access, and Splunk SOAR appear in the public material as the surrounding controls. A PM copies the pattern as an evaluation set and a human approval, not as an automation rate. No time-saved percentage is stored because none is established as this customer''s result.', 'Analysts re-read the same incident across products. A generated summary that files itself, or that isolates a host, skips the person who is accountable for a high-impact action. A demo click-path is easy to paste into a runbook and wrong as a procedure.', 'The public paper describes AI that helps the analyst see the incident. Instant Attack Verification is described as a check before an automated response is trusted. The February 2026 APJC note on the agentic SOC is an architecture argument, not a customer''s metric. The CiscoKorea video shows the product flow and stays a reference, not a script.', 'Give the SOC a written evaluation set and a rule that containment is a human decision. Share the governance forum with the Webex security-LLM track. Keep the schedules separate.', 'The SOC can show which summaries a person accepted. It does not show a percentage of time saved.',
  'cross_industry', 'Cross-industry', 'security_operations', 'Security operations', 'APAC', array['Incident-response policy', 'Change control for containment', 'NIST AI RMF'],
  'Enterprise SOC', 'hybrid', 'Hybrid SOC platform', 'XDR gathers the incident, an AI assistant drafts the summary, Instant Attack Verification checks the proposed response, and a person approves high-impact containment. Talos provides intelligence. Secure Access and Splunk SOAR are in the flow only when those products are already deployed.', 'high',
  'Amounts and durations are planning bands for an SOC pilot. They are not a quote and not a time-saved result.', 400000, 1800000, 'L',
  4, 10, 12, 24,
  array['Cisco XDR', 'Cisco Talos', 'Cisco Secure Access', 'Splunk SOAR'], array[]::text[], array['Incident summary draft', 'Instant Attack Verification', 'Analyst assistance'], array['Human approval for high-impact actions', 'Evaluation set', 'Existing containment playbook'], array['XDR', 'SOC', 'Instant Attack Verification', 'incident summary', 'agentic SOC'],
  array['An evaluation set of past incidents', 'A rule that high-impact containment needs a person', 'A comparison of the draft summary with the evidence', 'A note that the CiscoKorea video is a demo'], array['Pasting the video click-path into the runbook', 'A time-saved percentage', 'Unattended isolation', 'Foundation-model training on customer incidents'], array['Every evaluation incident has a person who accepted or rejected the draft', 'High-impact actions in the pilot were approved by a person', 'The runbook does not cite a video timestamp as a step'], 'published', array['Published pattern: the XDR AI paper describes assistance for the analyst, including summaries, not an unattended SOC.', 'Published pattern: Instant Attack Verification is described as a check so an automated response can be trusted.', 'Planning outcome: this pilot measures accept-or-reject on a frozen incident set. It does not publish a time-saved percentage.'],
  'https://www.youtube.com/watch?v=pYz-1Qr1AsY', 'CiscoKorea demo: AI-assisted security operations with Cisco XDR', '2026-02-24'
);
