insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('c9ee4738-59f3-4cf2-a0ad-7d37e3a5d471', 'c0445a81-159a-4efb-a7a1-4c850784412b', 0, 'business_case', 'Business case (1)', 'case: CSCO-XDR-SOC-001
title: AI-assisted security operations with Cisco XDR
industry: Cross-industry (cross_industry)
segment: Security operations
solutions: Cisco XDR, Cisco Talos, Cisco Secure Access, Splunk SOAR
partners: 
aliases: XDR, SOC, Instant Attack Verification, incident summary, agentic SOC
fidelity: primary_source
Cisco XDR''s public AI story is a draft for the analyst: summarize the incident, point at the evidence, and let a person decide. Instant Attack Verification, Talos, Secure Access, and Splunk SOAR appear in the public material as the surrounding controls. A PM copies the pattern as an evaluation set and a human approval, not as an automation rate. No time-saved percentage is stored because none is established as this customer''s result.

Problem: Analysts re-read the same incident across products. A generated summary that files itself, or that isolates a host, skips the person who is accountable for a high-impact action. A demo click-path is easy to paste into a runbook and wrong as a procedure.', 516, '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.048337,0.000000,0.000000,0.000000,0.000000,0.241684,0.000000,0.048337,-0.048337,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.145010,-0.386695,0.048337,0.000000,0.096674,-0.048337,0.000000,0.000000,0.000000,-0.096674,0.000000,-0.241684,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.096674,0.000000,0.193347,-0.096674,0.000000,0.000000,0.000000,-0.048337,0.000000,0.000000,0.000000,0.000000,0.048337,0.000000,0.048337,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.048337,0.000000,0.048337,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.048337,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.096674,0.145010,-0.048337,0.000000,-0.048337,0.048337,0.000000,0.000000,0.000000,0.048337,0.000000,0.000000,0.000000,0.048337,0.000000,0.000000,0.000000,0.048337,0.000000,0.000000,-0.096674,0.000000,0.000000,0.000000,0.000000,0.000000,-0.435031,0.048337,0.000000,0.000000,-0.048337,0.000000,0.000000,0.000000,0.000000,0.048337,0.000000,0.000000,-0.048337,0.048337,0.000000,0.000000,-0.145010,0.048337,0.000000,0.096674,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.048337,0.000000,0.000000,0.000000,-0.048337,0.048337,0.000000,0.000000,0.000000,0.048337,-0.096674,0.000000,0.000000,0.000000,0.000000,0.048337,-0.048337,0.000000,-0.096674,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000