insert into risks (case_id, risk_code, title, description, category, probability, impact, response_strategy, mitigation, contingency, owner_role, trigger_condition) values ('8be6569f-885a-40c8-a3a6-e89c4ddcd776', 'R3', 'Plant projects are retained for model training', 'The release says customer data is not used to train the underlying models. The contract has to say the same.', 'ai_governance', 2, 5, 'mitigate', 'Legal compares the order form with the 31 October 2023 statement before prompts start.', 'Stop the pilot if the terms differ.', 'Legal', 'A term allows training on customer content');
