insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('ff676ff0-5b8a-4feb-a27c-2b69278c2a1b', '8be6569f-885a-40c8-a3a6-e89c4ddcd776', 0, 'business_case', 'Business case (1)', 'case: IND-SIE-COP-001
