insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('990bcb25-eb4b-4afe-a4aa-73d56fda4866', '9ad6f613-79ae-4ab1-a1d9-e6b050a39e9c', 0, 'business_case', 'Business case (1)', 'case: IND-DEERE-SPRAY-001
title: John Deere See & Spray targeted herbicide application
industry: Agriculture (agriculture)
segment: Growers and custom applicators
solutions: See & Spray, ExactApply, John Deere Operations Center
partners: 
aliases: See and Spray, herbicide, targeted spray, corn, soybean, cotton, fallow
fidelity: primary_source
See & Spray uses boom-mounted cameras and onboard processors to spray herbicide only where a weed is recognized. John Deere''s 18 September 2024 release says customers saved an estimated 8 million gallons of herbicide mix on more than 1 million acres in the 2024 season, with an average 59 percent herbicide savings on corn, soybean, and cotton in the United States. Cameras scan over 2,100 square feet per second at up to 15 mph. Customers pay for the acres where the technology is used. A PM copying this pattern separates those published figures from a grower''s own as-applied maps.

Problem: Broadcast spraying puts herbicide on crop and on bare ground, not only on weeds. That spends chemical, water, and stops, and it is a poor fit for a stewardship target. A camera system that cannot show where it sprayed leaves the grower with a vendor percentage and no field record.', 611, '[0.000000,0.000000,0.000000,0.000000,0.000000,0.045502,-0.045502,0.000000,-0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.045502,-0.227508,0.000000,0.000000,0.045502,0.000000,0.000000,-0.182006,0.000000,-0.091003,0.045502,-0.364013,0.000000,-0.045502,0.045502,0.000000,0.000000,-0.045502,0.000000,0.000000,0.091003,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.000000,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.227508,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.000000,-0.091003,0.000000,-0.091003,0.045502,0.000000,0.000000,-0.045502,0.091003,0.000000,0.000000,0.000000,0.000000,-0.091003,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.000000,0.000000,0.045502,0.000000,0.000000,-0.045502,0.000000,0.000000,0.091003,0.000000,0.091003,0.000000,0.045502,0.000000,0.000000,0.000000,0.045502,-0.136505,0.000000,-0.045502,0.000000,0.000000,0.045502,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.045502,0.000000,-0.091003,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.045502,-0.091003,0.000000,-0.091003,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.091003,0.000000,0.000000,0.000000,0.000000,0.091003,