insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('b2addbb3-32ae-4ec3-a671-3e6cf5d388ff', '12c1b276-5b40-43f8-a8b5-3c826612f17d', 0, 'business_case', 'Business case (1)', 'case: IND-MOD-MRNA-001
title: Moderna mRNA design and the AWS digital platform
industry: Life sciences (life_sciences)
segment: Biopharma research and early manufacturing
solutions: Drug Design Studio, Automated mRNA manufacturing, AWS analytics and machine learning
partners: Amazon Web Services
aliases: Moderna, mRNA, mRNA-1273, Drug Design Studio, AWS, vaccine design
fidelity: primary_source
Moderna runs its Drug Design Studio and manufacturing data path on AWS. Public AWS accounts describe a digital loop from sequence design, through machine learning, to an automated preclinical plant. The COVID-19 timeline is published in two forms, 42 days and 25 days, and this record keeps both with their sources. A PM using the story plans a design-to-batch path, a human quality review, and a citation rule so the two timelines are never collapsed.

Problem: mRNA constructs used to take years to reach even preclinical work. Sequence choice, compute, lab execution, and quality review sat in different systems. Cryo-EM and other instruments add tens of terabytes a day. A single heroic timeline in a slide hides which source said 25 days and which said 42.', 579, '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.134840,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.044947,0.000000,0.000000,0.000000,0.044947,-0.224733,0.000000,0.000000,0.044947,-0.134840,0.000000,-0.089893,0.000000,-0.134840,0.044947,-0.539360,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.179787,-0.044947,0.000000,0.000000,0.000000,-0.179787,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.044947,0.000000,0.044947,0.000000,0.000000,0.000000,0.179787,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.089893,0.000000,-0.044947,0.044947,0.000000,0.000000,-0.044947,0.000000,0.000000,0.000000,0.000000,0.000000,-0.044947,0.089893,0.000000,0.000000,0.000000,0.000000,-0.044947,0.000000,0.000000,0.089893,0.000000,0.089893,-0.089893,0.000000,-0.044947,0.179787,-0.044947,0.044947,-0.089893,0.089893,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.089893,0.044947,0.000000,0.044947,0.000000,0.000000,-0.044947,0.000000,0.000000,0.000000,0.000000,0.000000,-0.044947,0.044947,0.000000,0.179787,0.000000,0.000000,0.000000,0.000000,0.000000,0.089893,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.044947,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.134840,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.089893,0.000000,0.000000,0.000000,0.000000,0.000000,0.134840,-0.044947,0.000000,0.000000,0.000000,0.000000,0.000000,-0.089893,0.000000,0.00