insert into case_chunks (id, case_id, chunk_index, section, heading, content, token_estimate, embedding) values ('8c196771-571d-4fba-aa06-a61f38a69f04', '23d52212-509e-4aaa-ad4f-ab2ee1a16b80', 6, 'scope', 'Scope, assumptions, and constraints (1)', 'case: IND-DBS-AI-001
title: DBS industrialized AI and the published value claim
industry: Financial services (financial_services)
segment: Retail and corporate bank
solutions: Model and use-case registry, PURE governance, Generative copilot pattern
partners: 
aliases: DBS, PURE, model registry, Evident AI Index, Singapore bank, responsible AI
fidelity: primary_source
In scope
- A registry with owner, purpose, and value method for every in-scope model
- A PURE review on new use cases
- One generative copilot with a named human decision
- A citation note when DBS''s published counts are used externally

Out of scope
- Adopting SGD 1 billion as this bank''s target
- Unattended credit or complaint decisions
- A second AI governance forum beside the existing one

Assumptions
- An inventory of current models can be extracted from the teams that trained them. (owner: Model risk, status: open)
- Finance will accept the value method or mark the use case as unmeasured. (owner: Finance partner, status: open)

Constraints
- [regulatory] Customer-facing recommendations stay explainable to the reviewer who owns the use case.
- [organizational] A model with no owner is not in production. It is an issue.', 603, '[-0.049147,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.098295,-0.049147,0.098295,-0.147442,0.049147,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.049147,-0.344031,0.000000,0.000000,0.049147,0.000000,0.049147,-0.049147,0.000000,-0.049147,0.000000,-0.245737,0.098295,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.049147,0.000000,0.000000,-0.098295,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,-0.196589,0.000000,0.000000,0.000000,0.000000,0.000000,-0.294884,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.049147,0.000000,0.147442,-0.049147,0.000000,-0.098295,0.000000,0.000000,0.000000,-0.049147,0.098295,0.000000,0.000000,0.000000,0.147442,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,-0.147442,0.049147,-0.049147,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,-0.196589,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,-0.098295,0.196589,-0.098295,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,-0.049147,0.098295,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,-0.049147,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.049147,0.000000,0.000000,0.000000,0.098295,0.000000,0.000000,0.000000,0.000000,0.000000,0.098295,0.000000,0.000000,0.000000,0.098295,0.000000,0.049147,0.000000,0.00